cd "$(pwd)" && python3 -c "
import xml.dom.minidom
ns='http://schemas.openxmlformats.org/wordprocessingml/2006/main'
with open('unpacked/word/document.xml') as f:
    dom = xml.dom.minidom.parse(f)
def localname(tag): return tag.split(':')[-1]
def get_text(node):
    parts=[]
    for t in node.getElementsByTagName('w:t'):
        parts.append(t.firstChild.nodeValue if t.firstChild else '')
    return ''.join(parts)
body=dom.getElementsByTagName('w:body')[0]
for i,p in enumerate([e for e in body.childNodes if getattr(e,'nodeType',0)==1 and localname(e.tagName)=='p']):
    ppr = p.getElementsByTagName('w:pPr')
    pstyle = ''
    if ppr:
        st = ppr[0].getElementsByTagName('w:pStyle')
        if st and st[0].getAttribute('w:val'): pstyle = st[0].getAttribute('w:val')
    text = get_text(p)
    runs = p.getElementsByTagName('w:r')
    # Check first run rPr
    props = []
    for r in runs:
        rpr = r.getElementsByTagName('w:rPr')
        if rpr:
            for child in rpr[0].childNodes:
                if getattr(child,'nodeType',0)==1:
                    props.append(localname(child.tagName))
    print(f'[{i}] style={pstyle!r} props={list(dict.fromkeys(props))} text={text[:80]!r}')
"
